import { readFileSync, writeFileSync } from "node:fs";
import { parseCsv, toCsv } from "./.cursor/scripts/tracker-lib.mjs";
const T = "2026-11-04", R = "upgrade/findings/precheck-2026-11-04.md";
const t = parseCsv(readFileSync("upgrade/tracker.csv","utf8"));
const rows = t.rows;
const get = id => { const r = rows.find(x => x.ID === id); if (!r) throw new Error("missing "+id); return r; };
const upd = (id, f) => { const r = get(id); const before = r.Status; Object.assign(r, f, { "Last checked": T }); if (f.Status && f.Status !== before) r["Status since"] = T; };
const add = r => { if (rows.some(x => x.ID === r.ID)) throw new Error("dup "+r.ID); rows.push({ Block:"0", Side:"Customer", "Last checked":T, "Status since":T, ...r }); };

upd("G0.2", { Notes: "precheck-paste.txt fails primary (is_replica true), psql (SQLAlchemy output) and coverage (shop only; ledger, files, postgres, cloudsqladmin missing); provenance unknown (no run_at). See Q-17 Q-18 Q-19 and "+R });
upd("G0.3", { Notes: "Provider outputs not in precheck-paste.txt and B0-04 evidence precheck/precheck-18.json not found, so clean is unverified; see Q-20" });
upd("G0.4", { Notes: "F-3-01 F-3-02 F-6e-01 added from precheck-paste.txt; 6a 6c 6d empty but unconfirmed and 6b invalid (replica) until the psql primary rerun (Q-17); "+R });
upd("G0.5", { Notes: "6 publications in shop map to no consumer (C-pub-* rows, Q-23 to Q-28); slots unread because the run was on a replica" });
upd("B0-03", { Notes: "precheck-paste.txt parsed 2026-11-04: replica, SQLAlchemy not psql, shop only, looks edited; rerun on primary with psql requested in Q-17 Q-18 Q-19" });
upd("B0-04", { Status: "Blocked", Notes: "Was Done, but Evidence precheck/precheck-18.json is not in the workspace and Done when also needs operations describe JSON and instances describe YAML; waiting on paste (Q-20)" });
upd("B0-05", { Evidence: R, Notes: "Parsed precheck-paste.txt; run invalid (replica, not psql, one database), so reparse after the rerun" });
upd("B0-07", { Notes: "Slots still unread (replica run); 6 publications found in shop, see C-pub-* rows" });
upd("F-5b-01", { Notes: "precheck-paste.txt 5b lists 2 unlogged tables, not 4 (Q-22); 5a shows both relkind r; has_generated_columns not returned; overdue since 2026-11-03" });
upd("F-6g-01", { Notes: "PR open 3 days; still listed in precheck-paste.txt 6g (unconfirmed run)" });
upd("Q-12", { Notes: "pglogical 2.4.5 installed in shop (precheck-paste.txt section 3); 8e not run; see F-3-01" });
upd("Q-15", { Notes: "precheck-paste.txt 4b shows 6 publications in shop, not 3; tracked per publication in Q-23 to Q-28" });

const f = (id, item, notes, gates, deps="") => add({ ID:id, Type:"Finding", Stream:"Catalog", Item:item, "Owner role":"DBA", Owner:"Sam Ortiz", "Run by":"Both", "Depends on":deps, Gates:gates, Status:"Waiting on customer", Evidence:"upgrade/results/precheck-paste.txt", Notes:notes });
f("F-6e-01", "promote_trigger_file set from configuration file (removed in 16)", "precheck-paste.txt 6e, replica run; probably provider-managed (Inferred); confirm against databaseFlags (Q-20); if customer-set remove via B1-03", "G0.4");
f("F-3-01", "pglogical 2.4.5 installed in shop with no known consumer", "precheck-paste.txt section 3 and 5a; 8e not run; drop only after Q-12 confirms nothing uses it", "G0.4 G0.5", "Q-12");
f("F-3-02", "vector 0.5.1 installed in shop; target version and reindex unplanned", "precheck-paste.txt section 3; 8f and 8g not run; feeds B1-06 and B1-14", "G0.4");

const q = (id, item, done, gates, extra={}) => add({ ID:id, Type:"Question", Stream:"Discovery", Item:item, "Done when":done, "Owner role":"DBA", Owner:"Sam Ortiz", "Run by":"Human", Gates:gates, Status:"Waiting on customer", ...extra });
q("Q-17", "Rerun the current precheck.sql with psql on the primary, unedited, ideally as a role with pg_read_all_stats", "precheck-<db>.txt with == headers and is_replica f", "G0.2", { Notes:"precheck-paste.txt was a replica run through SQLAlchemy" });
q("Q-18", "Precheck files for ledger, files and postgres; can cloudsqladmin be connected to?", "One file per connectable database, or a note for cloudsqladmin", "G0.2");
q("Q-19", "Was precheck-paste.txt edited or produced from a modified kit?", "Answer, plus an unedited rerun", "G0.2", { Notes:"Section 0 lacks run_at, 5b lacks relkind and has_generated_columns, 2b has 4 of 20 rows, 6f has 3 of 7 databases, 8a to 8g missing" });
q("Q-20", "Paste the provider precheck JSON, operations describe JSON and instances describe YAML", "All three pasted into upgrade/results", "G0.3", { "Depends on":"B0-04", Notes:"B0-04 evidence precheck/precheck-18.json not found in the workspace" });
q("Q-21", "Source minor version conflict: project.json says 14.24, replica reports 14.21. What is the primary on, and what is the provider current 14.x minor?", "Primary section 0 version and instances describe output", "G0.6", { Notes:"precheck-paste.txt section 0; matters for output_plugin_libraries [S-21]" });
