pubs.forEach((p, i) => {
  const cid = "C-pub-" + p.replace(/_/g, "-");
  add({ ID:cid, Type:"Consumer", Stream:"CDC", Item:"Publication "+p+" in database shop (consumer unknown)", "Owner role":"CDC owner", Owner:"unknown", "Run by":"Both", Gates:"G0.5", Status:"Waiting on customer", Evidence:"upgrade/results/precheck-paste.txt", Notes:"precheck-paste.txt section 4b; 8c not run", Auth:"unknown", Path:"cdc" });
  add({ ID:"Q-"+(23+i), Type:"Question", Stream:"CDC", Item:"Who consumes publication "+p+", and with what connector, version and plugin? Is it C-analytics-cdc?", "Done when":"Owner and connector named on "+cid, "Owner role":"CDC owner", Owner:"unknown", "Run by":"Human", "Depends on":cid, Gates:"G0.5", Status:"Waiting on customer" });
});

// keep new rows grouped: insert after the last existing row of the same type
writeFileSync("upgrade/tracker.csv", toCsv(rows, t.header));
console.log("rows:", rows.length);
' && node .cursor/scripts/tracker-check.mjs upgrade/tracker.csv

